import { useQueryClient } from '@tanstack/react-query';
import { useMutation, useQuery } from '@tanstack/react-query';

function TodoList() {
  const queryClient = useQueryClient();

  const { data: todos } = useQuery({
    queryKey: ['todos'],
    queryFn: fetchTodos,
  });

  const addTodo = useMutation({
    mutationFn: (newTodo: { title: string }) =>
      fetch('/api/todos', {
        method: 'POST',
        body: JSON.stringify(newTodo),
      }).then((res) => res.json()),
    onSuccess: () => {
      // Mark all 'todos' queries as stale and refetch
      queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  });

  return (
    <button onClick={() => addTodo.mutate({ title: 'New task' })}>
      Add Todo
    </button>
  );
}

const addTodoOptimistic = useMutation({
  mutationFn: (newTodo: { title: string }) =>
    fetch('/api/todos', {
      method: 'POST',
      body: JSON.stringify(newTodo),
    }).then((res) => res.json()),

  onMutate: async (newTodo) => {
    await queryClient.cancelQueries({ queryKey: ['todos'] });

    const previousTodos = queryClient.getQueryData(['todos']);

    queryClient.setQueryData(['todos'], (old: any) => [
      ...old,
      { id: Date.now(), title: newTodo.title, completed: false },
    ]);

    return { previousTodos };
  },

  onError: (_err, _newTodo, context) => {
    if (context?.previousTodos) {
      queryClient.setQueryData(['todos'], context.previousTodos);
    }
  },

  onSettled: () => {
    queryClient.invalidateQueries({ queryKey: ['todos'] });
  },
});

queryClient.invalidateQueries({
  queryKey: ['todos'],
  predicate: (query) => {
    // Only invalidate queries on page 1 after adding a new item
    const page = query.queryKey[1]?.page;
    return page === 1;
  },
});
